# Initially generated by GitHub Copilot.
"""Commit staged changes across repos listed in MAM-basics.code-workspace.

Usage:
    .venv/Scripts/python.exe py/main_commit_across_repos.py --message "Short summary"
    .venv/Scripts/python.exe py/main_commit_across_repos.py --message-file .novc/commit_msg_shared.txt
    .venv/Scripts/python.exe py/main_commit_across_repos.py --message "Short summary" --dry-run
    .venv/Scripts/python.exe py/main_commit_across_repos.py --message "Short summary" --and-push
"""

import argparse
import json
import os
from pathlib import Path
import subprocess
import tempfile

REPO_ROOT = Path(__file__).resolve().parent.parent
DEFAULT_WORKSPACE_FILE = REPO_ROOT / "MAM-basics.code-workspace"


def _parse_args():
    parser = argparse.ArgumentParser(description=__doc__)
    msg_group = parser.add_mutually_exclusive_group(required=True)
    msg_group.add_argument(
        "--message", help="Commit message text to reuse in every repo"
    )
    msg_group.add_argument(
        "--message-file",
        help="Path to a UTF-8 text file whose contents become the commit message",
    )
    parser.add_argument(
        "--workspace-file",
        default=str(DEFAULT_WORKSPACE_FILE),
        help="Path to the .code-workspace file listing repos to inspect",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Show which repos would be committed and with which message, without committing",
    )
    parser.add_argument(
        "--and-push",
        action="store_true",
        help="Push each repo after a successful commit",
    )
    return parser.parse_args()


def _load_repo_dirs(workspace_file):
    with open(workspace_file, "r", encoding="utf-8") as file_obj:
        workspace = json.load(file_obj)
    workspace_dir = workspace_file.parent
    repo_dirs = []
    for folder in workspace["folders"]:
        repo_dir = (workspace_dir / folder["path"]).resolve()
        if not repo_dir.is_dir():
            raise FileNotFoundError(f"Workspace folder not found: {repo_dir}")
        repo_dirs.append(repo_dir)
    return repo_dirs


def _read_message(message, message_file):
    if message_file is not None:
        with open(message_file, "r", encoding="utf-8") as file_obj:
            commit_message = file_obj.read()
    else:
        commit_message = message
    if not commit_message:
        raise ValueError("Commit message must not be empty")
    return commit_message


def _has_staged_changes(repo_dir):
    result = subprocess.run(
        ["git", "-C", str(repo_dir), "diff", "--cached", "--quiet", "--exit-code"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        check=False,
    )
    if result.returncode in (0, 1):
        return result.returncode == 1
    raise RuntimeError(
        result.stderr.strip() or f"Failed to inspect staged changes in {repo_dir}"
    )


def _get_staged_summary(repo_dir):
    result = subprocess.run(
        ["git", "-C", str(repo_dir), "diff", "--cached", "--numstat"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            result.stderr.strip() or f"Failed to summarize staged changes in {repo_dir}"
        )
    lines = [line for line in result.stdout.splitlines() if line.strip()]
    insertions = 0
    deletions = 0
    for line in lines:
        added_str, deleted_str, _path = line.split("\t", 2)
        if added_str != "-":
            insertions += int(added_str)
        if deleted_str != "-":
            deletions += int(deleted_str)
    return {
        "files_changed": len(lines),
        "insertions": insertions,
        "deletions": deletions,
    }


def _commit_repo(repo_dir, message_file):
    result = subprocess.run(
        ["git", "-C", str(repo_dir), "commit", "-F", str(message_file)],
        capture_output=True,
        text=True,
        encoding="utf-8",
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or result.stdout.strip())
    print(f"Committed {repo_dir.name}")


def _push_repo(repo_dir):
    result = subprocess.run(
        ["git", "-C", str(repo_dir), "push"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or result.stdout.strip())
    print(f"Pushed {repo_dir.name}")


def _show_dry_run(repo_dir, commit_message, staged_summary, *, and_push):
    print(f"Would commit {repo_dir.name}")
    print(
        "Summary: "
        f"{staged_summary['files_changed']} staged files, "
        f"{staged_summary['insertions']} insertions, "
        f"{staged_summary['deletions']} deletions"
    )
    if and_push:
        print("Would push after commit")
    print("Commit message:")
    print(commit_message)
    print("---")


def main():
    args = _parse_args()
    workspace_file = Path(args.workspace_file).resolve()
    commit_message = _read_message(args.message, args.message_file)
    repo_dirs = _load_repo_dirs(workspace_file)
    matching_repo_count = 0
    if args.dry_run:
        for repo_dir in repo_dirs:
            if not _has_staged_changes(repo_dir):
                continue
            staged_summary = _get_staged_summary(repo_dir)
            _show_dry_run(
                repo_dir, commit_message, staged_summary, and_push=args.and_push
            )
            matching_repo_count += 1
    else:
        with tempfile.NamedTemporaryFile(
            mode="w", encoding="utf-8", delete=False, suffix=".txt"
        ) as tmp_file:
            tmp_file.write(commit_message)
            tmp_path = Path(tmp_file.name)
        try:
            for repo_dir in repo_dirs:
                if not _has_staged_changes(repo_dir):
                    continue
                _commit_repo(repo_dir, tmp_path)
                if args.and_push:
                    _push_repo(repo_dir)
                matching_repo_count += 1
        finally:
            os.unlink(tmp_path)
    if matching_repo_count == 0:
        print("No staged changes found in any workspace repo.")
    elif args.dry_run:
        print(f"Dry run found staged changes in {matching_repo_count} repos.")
    elif args.and_push:
        print(f"Committed and pushed staged changes in {matching_repo_count} repos.")
    else:
        print(f"Committed staged changes in {matching_repo_count} repos.")


if __name__ == "__main__":
    main()
